package com.disasterinfo.eodiisseo.collection.operations;
import org.junit.jupiter.api.Test;import java.time.Instant;import java.util.UUID;import java.nio.charset.StandardCharsets;import static org.junit.jupiter.api.Assertions.*;
class CollectionHeartbeatWireCodecTest {
 CollectionWorkerCommandBoundary.Heartbeat request(){return new CollectionWorkerCommandBoundary.Heartbeat(UUID.randomUUID(),UUID.randomUUID(),UUID.randomUUID(),UUID.randomUUID(),UUID.randomUUID(),1,2,Instant.now().plusSeconds(30),new byte[64]);}
 @Test void exactTypedEnvelopeRoundTripsWithoutCredentials(){var r=request();var bytes=CollectionHeartbeatWireCodec.encode(r);var restored=CollectionHeartbeatWireCodec.decode(bytes);assertEquals(r.digest(),restored.digest());assertArrayEquals(r.signature(),restored.signature());assertFalse(new String(bytes,StandardCharsets.UTF_8).contains("capability"));}
 @Test void unknownCommandsSqlAndCallbacksAreRejected(){var json=new String(CollectionHeartbeatWireCodec.encode(request()),StandardCharsets.UTF_8);for(String extra:new String[]{"sql","callback","password","route"})assertThrows(IllegalArgumentException.class,()->CollectionHeartbeatWireCodec.decode(json.replace("{","{\""+extra+"\":\"forbidden\",").getBytes(StandardCharsets.UTF_8)));}
 @Test void malformedOversizedAndNonIntegerEnvelopesAreRejected(){assertThrows(IllegalArgumentException.class,()->CollectionHeartbeatWireCodec.decode(new byte[4097]));assertThrows(IllegalArgumentException.class,()->CollectionHeartbeatWireCodec.decode(new byte[]{(byte)0xff}));var text=new String(CollectionHeartbeatWireCodec.encode(request()),StandardCharsets.UTF_8);assertThrows(IllegalArgumentException.class,()->CollectionHeartbeatWireCodec.decode(text.replace("\"fence\":1","\"fence\":1.5").getBytes(StandardCharsets.UTF_8)));}
}
